// src/components/Admin/AddProduct.js
import React, { useState } from 'react';
import './AddProduct.css';

function AddProduct({ addProduct }) {
  const [formData, setFormData] = useState({
    name: '',
    description: '',
    price: '',
    averagePreparationTime: '',
    category: 'Pizza',
    stock: '',
    image: ''
  });

  const handleSubmit = (e) => {
    e.preventDefault();
    if (formData.name && formData.price && formData.category && formData.averagePreparationTime) {
      addProduct({
        ...formData,
        price: parseFloat(formData.price),
        averagePreparationTime: parseInt(formData.averagePreparationTime, 10),
        stock: parseInt(formData.stock, 10) || 0,
        image: formData.image || 'https://via.placeholder.com/150/EEEEEE/808080?text=No+Image'
      });
      
      setFormData({
        name: '',
        description: '',
        price: '',
        averagePreparationTime: '',
        category: 'Pizza',
        stock: '',
        image: ''
      });
      
      alert('Product added successfully!');
    } else {
      alert('Please fill in all required fields (*).');
    }
  };

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  return (
    <div className="add-product-container">
      <h1>Add New Product</h1>

      <form onSubmit={handleSubmit} className="product-form">
        <div className="form-group">
          <label>Product Name *</label>
          <input type="text" name="name" value={formData.name} onChange={handleChange} required />
        </div>
        
        <div className="form-group">
          <label>Description</label>
          <input type="text" name="description" value={formData.description} onChange={handleChange} />
        </div>

        <div className="form-group">
          <label>Price (₹) *</label>
          <input type="number" name="price" value={formData.price} onChange={handleChange} required />
        </div>
        
        <div className="form-group">
          <label>Avg. Preparation Time (mins) *</label>
          <input type="number" name="averagePreparationTime" value={formData.averagePreparationTime} onChange={handleChange} required />
        </div>

        <div className="form-group">
          <label>Category *</label>
          <select name="category" value={formData.category} onChange={handleChange}>
            <option>Pizza</option>
            <option>Burger</option>
            <option>Drink</option>
            <option>French fries</option>
            <option>Veggies</option>
          </select>
        </div>
        
        <div className="form-group">
          <label>Stock (units)</label>
          <input type="number" name="stock" value={formData.stock} onChange={handleChange} />
        </div>

        <div className="form-group">
          <label>Image URL (optional)</label>
          <input type="text" name="image" value={formData.image} onChange={handleChange} />
        </div>

        <button type="submit" className="submit-btn">
          Add Product
        </button>
      </form>
    </div>
  );
}

export default AddProduct;
